type IModules = {
  openAI?: typeof openai.OpenAI
  anthropic?: typeof anthropic
  azureOpenAI?: typeof azure
  cohere?: typeof cohere
  bedrock?: typeof bedrock
  google_vertexai?: typeof vertexAI
